from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        m = len(conflictingPairs)

        pairs_at = [[] for _ in range(n + 1)]
        for i in range(m):
            a, b = conflictingPairs[i]
            u = min(a, b)
            v = max(a, b)
            pairs_at[v].append((u, i))

        best = (0, -1)
        second_best = (0, -1)

        base_subarrays = 0
        benefit = [0] * m

        for R in range(1, n + 1):
            for u, i in pairs_at[R]:
                if u > best[0]:
                    second_best = best
                    best = (u, i)
                elif u >= second_best[0]:
                    second_best = (u, i)

            M1 = best[0]
            id1 = best[1]
            M2 = second_best[0]

            base_subarrays += R - M1

            if id1 != -1:
                benefit[id1] += M1 - M2

        return base_subarrays + max(benefit)
